insert into prep_instructions (test_name, instruction) values
  ($q$Blood Glucose (Fasting)$q$, $q$يُشترط الصيام من 6-8 ساعات (تُقبل الحالات من 6-10 ساعات).$q$),
  ($q$سكر صائم$q$, $q$يُشترط الصيام من 6-8 ساعات (تُقبل الحالات من 6-10 ساعات).$q$),
  ($q$سكر بعد الأكل$q$, $q$يُشترط احتساب الساعتين من ابتداء الأكل وبعد أخذ العلاج إذا وُجد. لا يُسمح بالأكل أثناء الساعتين، كما يُرجى الانتهاء من الأكل خلال 10 دقائق والحضور للمعمل قبل الميعاد بربع ساعة على الأقل.$q$),
  ($q$بول للحمل$q$, $q$يُفضّل أول بول في الصباح مع عدم تناول أي سوائل مساء اليوم السابق. إذا كانت النتيجة سلبية يُفضّل إجراء اختبار حمل من الدم لأنه أكثر حساسية.$q$),
  ($q$بول مزرعة$q$, $q$يُشترط غسل اليد والأعضاء التناسلية بالماء والصابون ثم تطهير فتحة البول بالديتول. اغسل مرة أخرى بالماء فقط لإزالة المطهر، ثم أفرغ أول نقط بول في دورة المياه وضع الباقي في البرطمان المعقم الذي يوفره المعمل. (يُفضّل) الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة. في حالة إرسال العينة من المنزل يُرجى وصولها للمعمل في نفس اليوم خلال ساعتين على الأكثر.$q$),
  ($q$تجميع بول 24 ساعة$q$, $q$فور القيام من النوم صباحًا، تبوّل في دورة المياه وسجّل الوقت، ثم اجمع كل نقطة بول بعد ذلك حتى اليوم التالي في نفس الميعاد (24 ساعة). لحفظ البول ضعه في الثلاجة.$q$),
  ($q$بصاق 3 أيام متتالية$q$, $q$يُشترط تجميع أول بصاق في الصباح بعد المضمضة بالماء عدة مرات وقبل الأكل. لا تُقبل عينات اللعاب. أرسل كل عينة منفصلة إلى المعمل في نفس اليوم. يمكن استنشاق بخار الماء الساخن في الصباح لتسهيل إعطاء العينة.$q$),
  ($q$تحاليل المني$q$, $q$يُشترط الامتناع عن الجماع أو الاحتلام لمدة 4 أيام متتالية. كما يُفضّل إعطاء العينة بالمعمل مع الاهتمام بوضع النقطة الأولى من المني في الزجاجة الخاصة بذلك. لا يُسمح بوجود مرافق أثناء إعطاء العينة داخل دورة المياه.$q$),
  ($q$Semen Analysis$q$, $q$يُشترط الامتناع عن الجماع أو الاحتلام لمدة 4 أيام متتالية. كما يُفضّل إعطاء العينة بالمعمل مع الاهتمام بوضع النقطة الأولى من المني في الزجاجة الخاصة بذلك. لا يُسمح بوجود مرافق أثناء إعطاء العينة داخل دورة المياه.$q$),
  ($q$المسحة القضيبية (البروستاتا)$q$, $q$يُشترط حجز البول لفترة قبل إجراء الفحص، و(يُفضّل) الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة.$q$),
  ($q$مسحة أمراض النساء$q$, $q$يُشترط عدم الجماع لمدة يومين وعدم غسيل المهبل يوم إجراء التحليل، و(يُفضّل) الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة.$q$),
  ($q$مزرعة البراز$q$, $q$يُشترط وصول العينة إلى المعمل في خلال ساعتين على الأكثر، ولا تُقبل أي عينة مرسلة في (بامبرز) الأطفال، و(يُفضّل) الامتناع عن المضاد الحيوي لمدة لا تقل عن 48 ساعة.$q$),
  ($q$براز الدم الخفي$q$, $q$يمتنع المريض لمدة 48 ساعة عن تناول جميع أنواع اللحوم والفجل وأدوية الروماتيزم وأي أدوية تحتوي على الأسبرين أو فيتامين ج أو الكورتيزون أو الحديد، كما لا يُسمح بأخذ مُلينات.$q$),
  ($q$PSA (Total)$q$, $q$يمتنع المريض 10 أيام قبل إجراء التحليل عن إدخال منظار أو قسطرة. لا يُجرى اختبار F. PSA إلا مع Total PSA.$q$),
  ($q$G6PD$q$, $q$يُشترط عدم إجراء التحليل بعد نقل الدم أو حدوث انتكاسة قبل مرور 4 أسابيع على الأقل.$q$),
  ($q$الحديد ومشتقاته$q$, $q$يُفضّل سحب العينة قبل بدء العلاج بالحديد أو نقل الدم.$q$),
  ($q$Catecholamine VMA$q$, $q$يجب تجميع البول 24 ساعة. يجب إيقاف الأدوية مثل قطرات الأنف والجيوب الأنفية وعقاقير الكحة وموسعات الشعب الهوائية أو مثبطات الشهية وأدوية الاكتئاب وأدوية القلب وأدوية ارتفاع ضغط الدم (alpha methyl dopa) بعد سماح الطبيب المعالج، وذلك لمدة أسبوع قبل سحب العينة. خلال التجميع يجب التوقف عن التدخين وعن تناول: الشاي والقهوة والشيكولاتة والموز والمكسرات والكولا والفاكهة الحمضية مثل البرتقال والليمون والفانيليا.$q$),
  ($q$HIAA-5$q$, $q$يجب تجميع البول 24 ساعة. يجب إيقاف الأدوية مثل قطرات الأنف والجيوب الأنفية وعقاقير الكحة وموسعات الشعب الهوائية أو مثبطات الشهية وأدوية الاكتئاب وأدوية القلب وأدوية ارتفاع ضغط الدم (alpha methyl dopa) بعد سماح الطبيب المعالج، وذلك لمدة أسبوع قبل سحب العينة. خلال التجميع يجب التوقف عن التدخين وعن تناول: الشاي والقهوة والشيكولاتة والموز والمكسرات والكولا والفاكهة الحمضية مثل البرتقال والليمون والفانيليا.$q$),
  ($q$Hydroxyproline$q$, $q$يجب تجميع البول 24 ساعة. يجب إيقاف الأدوية مثل قطرات الأنف والجيوب الأنفية وعقاقير الكحة وموسعات الشعب الهوائية أو مثبطات الشهية وأدوية الاكتئاب وأدوية القلب وأدوية ارتفاع ضغط الدم (alpha methyl dopa) بعد سماح الطبيب المعالج، وذلك لمدة أسبوع قبل سحب العينة. خلال التجميع يجب التوقف عن التدخين وعن تناول: الشاي والقهوة والشيكولاتة والموز والمكسرات والكولا والفاكهة الحمضية مثل البرتقال والليمون والفانيليا.$q$),
  ($q$دهنيات الدم$q$, $q$لا يُشترط الصيام إلا في حالة طلب الطبيب المعالج، ولبعض الحالات المرضية يتم طلب صيام من 12-16 ساعة.$q$),
  ($q$أدوية الربو$q$, $q$يُؤخذ الدواء بانتظام لمدة 5 أيام على الأقل، ويُشترط عدم القيء أو الإسهال لمدة 48 ساعة قبل إجراء التحليل.
